package io.ecosync.database;
public class DatabaseFailure extends RuntimeException {
 private final String code;
 public DatabaseFailure(String code){super(message(code));this.code=java.util.Set.of("DB_DISABLED","DB_DESTINATION_DENIED","DB_BUSY","DB_UNAVAILABLE","DB_SCHEMA_CHANGED","DB_REVALIDATION_REQUIRED","DB_AUTHENTICATION_FAILED","DB_ACCESS_DENIED","DB_INVALID_QUERY","DB_LIMIT","DB_CANCELLED","DB_TLS_FAILED").contains(code)?code:"DB_UNAVAILABLE";}
 private static String message(String code){return switch(java.util.Objects.toString(code,"")){case "DB_DISABLED"->"This connector is not active for the requested operation.";case "DB_DESTINATION_DENIED"->"This database destination is not allowed by the deployment.";case "DB_BUSY"->"The connector is busy. Try again after current reads finish.";case "DB_SCHEMA_CHANGED"->"The database schema changed. Inspect it and approve the current scope again.";case "DB_REVALIDATION_REQUIRED"->"Inspect the database again before approving the changed data scope.";case "DB_AUTHENTICATION_FAILED"->"The database rejected its configured credentials.";case "DB_ACCESS_DENIED"->"Your current role or data approval does not permit this operation.";case "DB_INVALID_QUERY"->"Check the selected columns, filters, ordering and limits.";case "DB_LIMIT"->"The database operation exceeded a resource limit.";case "DB_CANCELLED"->"This database read was cancelled or superseded.";case "DB_TLS_FAILED"->"The verified database TLS connection failed.";default->"Database operation could not be completed.";};}
 public String code(){return code;}
 public int status(){return switch(code){case "DB_ACCESS_DENIED"->403;case "DB_DISABLED","DB_SCHEMA_CHANGED","DB_REVALIDATION_REQUIRED","DB_CANCELLED"->409;case "DB_BUSY","DB_LIMIT"->429;case "DB_INVALID_QUERY","DB_DESTINATION_DENIED","DB_TLS_FAILED","DB_AUTHENTICATION_FAILED"->422;default->503;};}
}
